const (
	defaultBatchSize = 25
)

var (
	latestVersion     = semver.Version{Major: 1, Minor: 2}
	supportedVersions = semver.Versions{
		{Major: 1},
		{Major: 1, Minor: 1},
		latestVersion,
	}
)

type Lister interface {
	ListNamespaces(context.Context, *flipt.ListNamespaceRequest) (*flipt.NamespaceList, error)
	ListFlags(context.Context, *flipt.ListFlagRequest) (*flipt.FlagList, error)
	ListSegments(context.Context, *flipt.ListSegmentRequest) (*flipt.SegmentList, error)
	ListRules(context.Context, *flipt.ListRuleRequest) (*flipt.RuleList, error)
	ListRollouts(context.Context, *flipt.ListRolloutRequest) (*flipt.RolloutList, error)
}

type Exporter struct {
	store         Lister
	batchSize     int32
	namespaces    []string
	allNamespaces bool
}

func NewExporter(store Lister, namespaces string, allNamespaces bool) *Exporter {
	ns := strings.Split(namespaces, ",")

	return &Exporter{
		store:         store,
		batchSize:     defaultBatchSize,
		namespaces:    ns,
		allNamespaces: allNamespaces,
	}
}

// We currently only do minor bumps and print out just major.minor
func versionString(v semver.Version) string {
	return fmt.Sprintf("%d.%d", v.Major, v.Minor)
}

func (e *Exporter) Export(ctx context.Context, encoding Encoding, w io.Writer) error {
	var (
		enc       = encoding.NewEncoder(w)
		batchSize = e.batchSize
	)

	defer enc.Close()

	var namespaces = e.namespaces

	// If allNamespaces is "true", then retrieve all the namespaces, and store them in a string slice.
	if e.allNamespaces {
		var (
			remaining = true
			nextPage  string
		)

		intermediateNamespaces := make([]string, 0)

		for remaining {
			resp, err := e.store.ListNamespaces(ctx, &flipt.ListNamespaceRequest{
				PageToken: nextPage,
				Limit:     batchSize,
			})
			if err != nil {
				return fmt.Errorf("getting namespaces: %w", err)
			}

			nextPage := resp.NextPageToken
			remaining = nextPage != ""

			for _, ns := range resp.Namespaces {
				intermediateNamespaces = append(intermediateNamespaces, ns.Key)
			}
		}

		namespaces = intermediateNamespaces
	}

	for i := 0; i < len(namespaces); i++ {
		doc := new(Document)
		// Only provide the version to the first document in the stream.
		if i == 0 {
			doc.Version = versionString(latestVersion)
		}
		doc.Namespace = namespaces[i]

		var (
			remaining = true
			nextPage  string
		)

		// export flags/variants in batches
	// defaultReleaseChecker checks for the latest release
	// can be overridden for testing
	defaultReleaseChecker githubReleaseChecker = &githubReleaseCheckerImpl{
		client: github.NewClient(nil).Repositories,
	}
)

// Check checks for the latest release and returns an Info struct containing
// the current version, latest version, if the current version is a release, and
// if an update is available.
func Check(ctx context.Context, version string) (Info, error) {
	return check(ctx, defaultReleaseChecker, version)
}

// visible for testing
func check(ctx context.Context, rc githubReleaseChecker, version string) (Info, error) {
	i := Info{
		CurrentVersion: version,
	}

	cv, err := semver.ParseTolerant(version)
	if err != nil {
		return i, fmt.Errorf("parsing current version: %w", err)
	}

	release, err := rc.getLatestRelease(ctx)
	if err != nil {
		return i, fmt.Errorf("checking for latest release: %w", err)
	}

	if release != nil {
		var err error
		lv, err := semver.ParseTolerant(release.GetTagName())
		if err != nil {
			return i, fmt.Errorf("parsing latest version: %w", err)
		}

		i.LatestVersion = lv.String()

		// if current version is less than latest version, an update is available
		if cv.Compare(lv) < 0 {
			i.UpdateAvailable = true
			i.LatestVersionURL = release.GetHTMLURL()
		}
	}

